 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] in (1, 2, 3, 6)]
    paths = {}

    # Each marker emits its characteristic ray. Store generated cells so ray
    # intersections can be identified independently of write order.
    for r, c, color in markers:
        cells = []
        if color == 1:
            cells = [(r, c + 1, 5), (r, c + 2, 5), (r - 1, c + 2, 1)]
        elif color == 2:
            cells = [(r, c - d, 2 if d == 4 else 5) for d in range(1, 5)]
        elif color == 3:
            cells = [(r + d, c, 3 if d == 3 else 5) for d in range(1, 4)]
        elif color == 6:
            cells = [(r - d, c, 6 if d == 6 else 5) for d in range(1, 7)]
        paths[(r, c, color)] = [(rr, cc, v) for rr, cc, v in cells if 0 <= rr < h and 0 <= cc < w]

    # Draw all rays; an intersection of distinct rays becomes a 4.
    owners = {}
    for key, cells in paths.items():
        for rr, cc, value in cells:
            owners.setdefault((rr, cc), []).append((key, value))
    for (rr, cc), entries in owners.items():
        distinct = {key for key, _ in entries}
        g[rr][cc] = 4 if len(distinct) > 1 else entries[0][1]

    # Spawn the southwest 4-ray from each intersection, continuing to the edge.
    intersections = [pos for pos, entries in owners.items() if len({key for key, _ in entries}) > 1]
    for r, c in intersections:
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            g[rr][cc] = 4 if rr == h - 1 or cc == 0 else 4
            rr += 1
            cc -= 1

    # Original markers are retained, except generated intersections/rays do not
    # overwrite them (the demonstrations preserve all source markers).
    for r, c, color in markers:
        g[r][c] = color
    return g
